+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * Narrows the customer list. A customer matches when it satisfies both parts.
+ *
+ * <p>The name is split on whitespace into terms, and every term must appear, ignoring
+ * case and accents, in the customer's first name or last name. The statuses, when
+ * any are given, must include the customer's status.
+ *
+ * @param name     the text typed into the name filter; blank matches every name
+ * @param statuses the statuses to show; empty shows every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /**
+     * Returns a test for this filter. The name terms are normalised here, once, rather
+     * than once per customer, so build the predicate once per query.
+     */
+    public Predicate<Customer> toPredicate() {
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> allowed = statuses;
+        return customer -> {
+            if (!allowed.isEmpty() && !allowed.contains(customer.status())) {
+                return false;
+            }
+            String first = fold(customer.firstName());
+            String last = fold(customer.lastName());
+            return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+        };
+    }
+
+    private List<String> nameTerms() {
+        return Arrays.stream(WHITESPACE.split(name))
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::fold)
+                .toList();
+    }
+
+    /** Lower-cases and strips accents, so {@code Mäkinen} folds to {@code makinen}. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text.toLowerCase(Locale.ROOT), Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("");
+    }
+}
